'use strict';
// Original Engine Arena sculpture. Regenerate with scripts/generate_board3d_knight.cjs.
const ArenaKnightMesh=(()=>{
 const raw=atob(''),data=new DataView(Uint8Array.from(raw,c=>c.charCodeAt(0)).buffer),out=new Float32Array(data.byteLength/12*7);
 for(let i=0;i<data.byteLength;i+=12){const n=[6,8,10].map(k=>data.getInt16(i+k,true)/32767),l=Math.hypot(...n);out.set([...
 [0,2,4].map(k=>data.getInt16(i+k,true)/10000),...n.map(v=>v/l),1],i/12*7)}
 return out;
})();
if(typeof module!=='undefined')module.exports=ArenaKnightMesh;
